"""Справочник Frontier International. Формулы сверены с calcunit.tjs,
battlefuncattack.tjs, battlefunctacticsskill.tjs и battlefuncview.tjs из u8."""
from math import sqrt
from html import escape as esc

def table(columns, rows):
    return '<div class="scroll-table"><table><thead><tr>'+''.join(f'<th scope="col">{esc(str(c))}</th>' for c in columns)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{esc(str(v))}</td>' for v in r)+'</tr>' for r in rows)+'</tbody></table></div>'

def formula(text):
    return '<p class="formula"><code>'+esc(text)+'</code></p>'

def guides(page,register,illustration):
    attack_examples=[]
    for hp in (100,225,400,900):
        raw=85*sqrt(hp)/25
        attack_examples.append((hp,int(raw),int(raw/3)))
    damage="""<p>У раненого бойца падает сила удара, даже когда атака в карточке остаётся прежней. В расчёт входят его текущие ОЗ. Если ОЗ упали с 400 до 100, базовый урон сократится вдвое: игра извлекает из здоровья квадратный корень.</p>
<h2>Обычный удар</h2><p>А — атака бойца с боевыми поправками, З — защита цели, У — укрепление её стороны. Для расчёта защита не может быть ниже 1. Значение укрепления меньше 1 считается нулём.</p>"""+formula("Урон = ⌊(2 × А + 5) × √ОЗ атакующего / (З + 5 + √У)⌋")+"""<p>Скобки ⌊ ⌋ означают округление вниз. При атаке 40, здоровье 400 и защите цели 20 в открытом поле удар даст 68. Укрепление 100 прибавит к знаменателю 10. Та же атака даст 48. Это исходное значение до крита, преимуществ класса и защитных навыков.</p>
<h2>Ответный удар</h2><p>Для контратаки стороны меняются местами: используются атака и текущие ОЗ отвечающего бойца, защита и укрепление его противника. Игра делит результат на 3 до округления. Дальний удар по бойцу без дальнего ответа и «Разрез пространства» обнуляют ответный урон.</p>
<p>Сравнение при одинаковых характеристиках обоих бойцов: атака 40, защита 20, укрепление 0. В каждой строке у обоих указанное число ОЗ.</p>"""+table(("ОЗ","Обычный удар","Контратака"),attack_examples)+"""
<h2>Подставить свои значения</h2><p>Для ответного удара введите показатели бойца, который отвечает, и защиты цели его контратаки.</p>
<form class="damage-calculator"><label>Атака <input name="atk" type="number" value="40" min="1" required></label><label>Текущие ОЗ <input name="hp" type="number" value="400" min="1" required></label><label>Защита цели <input name="def" type="number" value="20" min="1" required></label><label>Укрепление цели <input name="land" type="number" value="0" min="0" required></label><output aria-live="polite">Удар 68 · Контратака 22</output></form>
<h2>Как пробивается защита</h2><p>При крите со «Смертельным критом» у цели сначала остаётся 75% защиты. Затем «Раскол шлема» умножает остаток на (100 − значение навыка) / 100. Множитель не может быть ниже 0,25. Следом «Разрез пространства» оставляет четверть того, что уцелело. После каждой из двух последних операций игра отбрасывает дробную часть.</p>
<p>Например, из 80 защиты «Раскол шлема» со значением 50 оставит 40. Если тот же удар обладает «Разрезом пространства», останется 10. Именно с этой защитой рассчитывается базовый урон. <a href="critical.html">Как крит изменит полученное число →</a></p>"""
    critical="""<p>Скорость нужна и для критического удара. Быстрый боец чаще наносит крит, медленная цель чаще его получает. При равной скорости у бойца со скоростью 100 шанс выше, чем в поединке двух бойцов со скоростью 25.</p><h2>Шанс в процентах</h2>"""+formula("Шанс = ⌊3 × √скорости атакующего − √скорости цели + бонус навыка + 5⌋")+"""<p>Берутся скорости после боевых поправок. Бонус даёт «Повышенный шанс крита». Минимальный шанс всегда 5%. Без навыка максимум 50%, с ним — 75%. Игра бросает целое число от 0 до 99. Если оно строго меньше итогового шанса, удар критический.</p>"""+table(("Скорость бойца","Скорость цели","Бонус","Шанс"),[(25,25,"—","15%"),(100,25,"—","30%"),(25,100,"—","10%"),(100,25,"+20","50%"),(400,25,"—","50% (предел)"),(400,25,"+20","75% (предел)")])+"""<h2>Сколько добавляет крит</h2><p>Обычный крит умножает базовый урон на 1,5 и отбрасывает дробную часть. «Смертельный крит» действует дважды. Перед расчётом урона он снижает защиту цели на четверть. После расчёта добавляет множитель (1 + значение навыка / 100) к обычным ×1,5.</p><p>Пусть у бойца атака 40 и 400 ОЗ, у цели защита 20 и нет укрепления. Обычный удар даст 68, обычный крит — 102. Со «Смертельным критом» 40 расчётная защита упадёт до 15: базовый удар станет равен 85, а крит даст ⌊85 × 1,5 × 1,4⌋ = 178. Остальные навыки здесь выключены.</p>"""
    ranks=[(r,level,10*(level-1)**2) for r,level in zip("SABCDEFG",range(150,79,-10))]
    growth="""<p>Каждый новый уровень требует больше опыта. В начале достаточно 10 единиц, чтобы перейти с первого уровня на второй. Для перехода с десятого на одиннадцатый нужно уже 190. Накопленный опыт сохраняется при повышении уровня.</p><h2>Пороги опыта</h2>"""+formula("Уровень = ⌊√(опыт / 10)⌋ + 1     •     Опыт для уровня L = 10 × (L − 1)²")+table(("Уровень","Всего опыта","До следующего уровня"),[(l,10*(l-1)**2,10*(2*l-1)) for l in (1,2,5,10,25,50)])+"""<h2>Максимум здоровья</h2><p>Каждый уровень после первого прибавляет четверть базовых ОЗ. Бонус считается от исходного здоровья. Боец с базой 120 получает по 30 ОЗ за уровень: на втором у него 150, на пятом — 240, на десятом — 390. Дробная часть отбрасывается. Предел — 9 999 ОЗ.</p><h2>Атака, защита и скорость</h2><p>У этих параметров своя формула от общего опыта. Поэтому два бойца с разной базой за одинаковую службу получат разную прибавку. Б — базовое значение характеристики.</p>"""+formula("Параметр = Б + ⌊Б × √опыта / 200 + ⌊√опыта / 25⌋⌋")+"""<p>При 1 000 опыта боец с базовой атакой 40 получит 47. На этом этапе расчёта верхняя граница — 999. Для боевого духа делители составляют 500 и 40 соответственно, верхняя граница — 99. Боевые изменения рассчитываются отдельно.</p><h2>Предел по рангу роста</h2>"""+table(("Ранг","Последний уровень","Предел опыта"),ranks)
    tactics="""<p>У атакующего тактического навыка есть собственная мощность. Её усиливает уровень командира. Для обычного удара важны текущие ОЗ бойца, а в формулу тактического урона они не входят.</p><h2>Урон по бойцу</h2><p>М — мощность эффекта, L — уровень командира, П — поправка атрибута. З и У — защита бойца и укрепление его стороны. Б — процент барьера от тактических навыков, С — процент заслона цели.</p>"""+formula("Урон = ⌊М × (1 + (L + П) / 100 − 0,02 × √З) × (1 − 0,02 × √У) × (1 − Б / 100) × (1 − С / 100)⌋")+"""<p>Возьмём мощность 200, уровень 20, поправку 0 и защиту 100. До укрепления и защитных навыков получается 200. При укреплении 25 останется 180. Барьер 20% и заслон 50% последовательно сократят его до 144 и 72. В боевом расчёте округляется результат всей формулы.</p><h2>Почему два защитных навыка работают по-разному</h2><p>Значения «Барьера от тактических навыков» собираются по отряду. «Заслон от тактических навыков» проверяется у конкретной цели. Два процента входят в разные множители: барьер 20 и заслон 50 вместе пропускают 40% урона, который прошёл защиту и укрепление.</p><h2>Лечение, воскрешение и ремонт стены</h2>"""+formula("Эффект = ⌊М × (1 + (L + П) / 100)⌋")+"""<p>Это базовая величина для лечения, воскрешения, создания барьера и восстановления укреплений. При мощности 150 и уровне 20 без поправки получится 180. Для разрушения стены игра дополнительно умножает результат на (1 − 0,03 × √У) и (1 − Б / 100). Укрепление 100 оставляет 70% силы такого удара по стене.</p>"""
    items=[("damage","Урон и контратака",damage,"scenes/division-roster","Отряд перед боем. Для расчёта удара важны текущие ОЗ каждого бойца."),
           ("critical","Критические удары",critical,"",""),("growth","Опыт, уровни и ранг роста",growth,"",""),
           ("tactical","Тактические навыки и защита от них",tactics,"","")]
    for slug,title,body,art,caption in items:
        page(slug+'.html',title,'mechanics.html','<div class="wrap guide-layout"><article><div class="crumb"><a href="mechanics.html">Механика Frontier</a></div><h1>'+title+'</h1>'+body+(illustration(art,caption) if art else '')+'</article></div>')
        register(title,slug+'.html','Механика Frontier')
    return '<ul class="reading-list">'+''.join(f'<li><a href="{slug}.html">{title}</a></li>' for slug,title,*_ in items)+'</ul>'
